}#include <Wire.h>
#include <LiquidCrystal_I2C.h>

// Инициализация LCD (адрес может быть 0x27 или 0x3F)
LiquidCrystal_I2C lcd(0x27, 16, 2);

const int interruptPin = 2;
volatile unsigned long pulseCount = 0;
unsigned long lastTime = 0;

// Коэффициент для СБМ-20 (мкЗв/ч на 1 CPM)
const float CONV_FACTOR = 0.0057;

void setup() {
  Serial.begin(9600);
  lcd.init();
  lcd.backlight();
  lcd.setCursor(0, 0);
  lcd.print("Dosimeter v1.0");
  lcd.setCursor(0, 1);
  lcd.print("Starting...");

  pinMode(interruptPin, INPUT_PULLUP);
  attachInterrupt(digitalPinToInterrupt(interruptPin), countPulse, FALLING);
  lastTime = millis();
  delay(2000);
}

void loop() {
  unsigned long currentTime = millis();

  // Обновление каждые 3 секунды для накопления статистики
  if (currentTime - lastTime >= 3000) {
    noInterrupts();
    unsigned long count = pulseCount;
    pulseCount = 0;
    interrupts();

    // Расчет CPM (импульсов в минуту)
    float cpm = (count / 3.0) * 60.0;  // т.к. замер за 3 секунды

    // Расчет мощности дозы в мкЗв/ч
    float doseRate = cpm * CONV_FACTOR;

    // Вывод в Serial
    Serial.print("CPM: ");
    Serial.print(cpm);
    Serial.print(" | мкЗв/ч: ");
    Serial.println(doseRate, 3);

    // Вывод на LCD
    lcd.clear();
    lcd.setCursor(0, 0);
    lcd.print("CPM:");
    lcd.print(cpm, 0);

    lcd.setCursor(0, 1);
    lcd.print(doseRate, 3);
    lcd.print(" uSv/h");

    lastTime = currentTime;
  }
}

void countPulse() {
  pulseCount++;
}
